import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from temperatureTrends ----
/** Synthetic monthly anomalies, 1880-2020. Modelled on GISTEMP's shape, not its values. */
type Anomaly = { date: Date; value: number };

const START_YEAR = 1880;
const END_YEAR = 2020;
const SMOOTHING_MONTHS = 121;

// mulberry32: a fixed seed keeps the series byte-identical across hot reloads.
function seeded(seed: number): () => number {
  return () => {
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function buildSeries(): Anomaly[] {
  const random = seeded(20260813);
  const series: Anomaly[] = [];
  for (let year = START_YEAR; year <= END_YEAR; year++) {
    for (let month = 0; month < 12; month++) {
      const decimalYear = year + month / 12;
      const progress = (decimalYear - START_YEAR) / (END_YEAR - START_YEAR);
      const trend = -0.28 + 1.25 * (0.35 * progress + 0.65 * progress ** 3);
      // 1940s warm bump and the 1960s dip that together make the mid-century plateau.
      const midCentury =
        0.1 * Math.exp(-(((year - 1942) / 12) ** 2)) - 0.07 * Math.exp(-(((year - 1965) / 10) ** 2));
      const multiYear =
        0.12 * Math.sin((2 * Math.PI * decimalYear) / 3.7) +
        0.08 * Math.sin((2 * Math.PI * decimalYear) / 6.3 + 1.1);
      const seasonal = 0.06 * Math.sin((2 * Math.PI * month) / 12 + 0.6);
      const value = trend + midCentury + multiYear + seasonal + 0.18 * (random() - 0.5);
      series.push({ date: new Date(Date.UTC(year, month, 1)), value: Math.round(value * 1000) / 1000 });
    }
  }
  return series;
}

function smooth(series: Anomaly[]): Anomaly[] {
  const half = Math.floor(SMOOTHING_MONTHS / 2);
  return series.map((d, i) => {
    const window = series.slice(Math.max(0, i - half), i + half + 1);
    return { date: d.date, value: window.reduce((sum, w) => sum + w.value, 0) / window.length };
  });
}

const temperatureAnomalies = buildSeries();
const temperatureTrend = smooth(temperatureAnomalies);

const MARGIN = { top: 28, right: 20, bottom: 36, left: 52 };

/** Below this the caption cannot fit beside the axis label, so it is dropped. */
const MIN_CAPTION_WIDTH = 380;

/** The dated readings to scatter, plus the smoothed series drawn as the trend line over them. */
export type Data = {
  anomalies: { date: Date; value: number }[];
  trend: { date: Date; value: number }[];
};

const DEMO: Data = { anomalies: temperatureAnomalies, trend: temperatureTrend };

export default function GlobalTemperatureTrends({ data = DEMO, width }:
  { data?: Data; width: number }) {
  const height = Math.round(width * 0.55);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const x = useMemo(
    () =>
      d3
        .scaleUtc()
        .domain(d3.extent(data.anomalies, (d) => d.date) as [Date, Date])
        .range([0, innerWidth]),
    [data, innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain(d3.extent(data.anomalies, (d) => d.value) as [number, number])
        .nice()
        .range([innerHeight, 0]),
    [data, innerHeight]
  );

  // Symmetric domain so the interpolator's midpoint lands exactly on zero anomaly.
  const color = useMemo(() => {
    const extreme = d3.max(data.anomalies, (d) => Math.abs(d.value)) ?? 1;
    return d3.scaleSequential([extreme, -extreme], d3.interpolateRdBu);
  }, [data]);

  const trendPath = useMemo(
    () =>
      d3
        .line<Anomaly>()
        .x((d) => x(d.date))
        .y((d) => y(d.value))
        .curve(d3.curveMonotoneX)(data.trend) ?? '',
    [data, x, y]
  );

  const xTicks: Tick[] = useMemo(
    () =>
      x
        .ticks(Math.max(3, Math.round(innerWidth / 90)))
        .map((v) => ({ value: d3.utcFormat('%Y')(v), offset: x(v) })),
    [x, innerWidth]
  );

  const yTicks: Tick[] = useMemo(
    () => y.ticks(6).map((v) => ({ value: d3.format('+.1f')(v), offset: y(v) })),
    [y]
  );

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Scatterplot of synthetic monthly temperature anomalies from 1880 to 2020, colored by sign, with a ten-year smoothed trend line"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        <line
          x1={0}
          x2={innerWidth}
          y1={y(0)}
          y2={y(0)}
          stroke="var(--muted)"
          strokeWidth={1}
        />
        {data.anomalies.map((d) => (
          <circle
            key={d.date.getTime()}
            cx={x(d.date)}
            cy={y(d.value)}
            r={1.8}
            fill={color(d.value)}
            fillOpacity={0.85}
          />
        ))}
        <path
          d={trendPath}
          fill="none"
          stroke="var(--text)"
          strokeWidth={2}
          strokeLinejoin="round"
          strokeLinecap="round"
        />
        <text x={4} y={-10} fill="var(--text)" fontSize={12} fontWeight={600}>
          Anomaly (°C)
        </text>
        {innerWidth >= MIN_CAPTION_WIDTH && (
          <text x={innerWidth} y={-10} fill="var(--muted)" fontSize={11} textAnchor="end">
            Synthetic series — not observed climate data
          </text>
        )}
      </g>

      {/* A warming curve with no provenance is the one output here that could mislead. */}
      <text x={MARGIN.left} y={height - 4} fill="var(--muted)" fontSize={10}>
        Synthetic data from a seeded generator, not GISTEMP or any real record.
      </text>
    </svg>
  );
}
